{
  "title": "迷雾中的古宅",
  "scene": "你站在一座古老的宅院前，四周弥漫着一层迷雾，空气中弥漫着一股淡淡的香气。据说这座宅院中藏有几百年前的奇珍异宝。你推开了吱呀作响的大门，一股阴冷的气息迎面扑来。在宅院的正中，摆放着一张古老的八仙桌，桌上静置着一本陈旧的古籍，似乎在诉说着什么。",
  "goal": "揭开古籍的秘密，找到宅院的秘密，并安全地离开。",
  "choices": [
    {
      "id": "A",
      "text": "仔细翻阅古籍，试图找出其中的线索。",
      "outcome": "你从古籍中找到了一张模糊的地图，地图上标记着宅院中的一个隐蔽房间。",
      "result": "partial",
      "next": "进入隐蔽房间"
    },
    {
      "id": "B",
      "text": "四处探索宅院，寻找其他可能的线索。",
      "outcome": "你找到了一些奇怪的脚印，看起来像是有人最近刚刚进入过这座宅院。",
      "result": "partial",
      "next": "追踪脚印"
    },
    {
      "id": "C",
      "text": "询问宅院周围的人，看是否有人知道些什么。",
      "outcome": "你并没有找到任何人的踪迹，周围的迷雾似乎变得更加浓厚。",
      "result": "fail",
      "next": "返回起点"
    }
  ]
}
